    }
    function close() {
        if (!scrim || closing) return;
        const s = scrim, back = opener, done = () => {
            clearTimeout(closing); closing = 0;
            if (bodyKill) bodyKill(); bodyKill = null; s.remove(); scrim = dlg = body = null;
            vr.inert = false; vr.classList.remove('jl-away');
            if (back) back.focus({ preventScroll: true });
            root.dispatchEvent(new CustomEvent('jali:close'));
        };
        if (calm.matches) { done(); return; }
        s.classList.remove('jl-in'); s.classList.add('jl-out');
        closing = setTimeout(done, 260);
    }
    for (const it of items) {
        it.orb.addEventListener('click', () => open(it));
        it.orb.addEventListener('focus', () => ctx.walkTo(it.i));
    }

    return {
        place, tick, close, refresh() { if (view) place(view); },
        points: () => items.map((it) => ({ el: it.orb, x: it.x, y: it.y, z: it.z })),
        look: () => ({ x: px, y: py }),
        destroy() {
            close(); clearTimeout(closing); clearTimeout(flash);
            if (scrim) { scrim.remove(); scrim = null; }
            root.removeEventListener('pointermove', onMove); root.removeEventListener('pointerleave', onLeave);
            root.removeEventListener('pointerenter', onEnter); root.removeEventListener('pointerdown', onDown);
            root.removeEventListener('pointerup', onUp); root.removeEventListener('pointercancel', onUp);
            vr.remove(); ret.remove(); root.classList.remove('jl-gaze');
            for (const p of ['--jl-sun', '--jl-sky', '--jl-warm']) root.style.removeProperty(p);
        },
    };
}

/*
 *  TILT // one shared, smoothed read of how the phone is being held.
 *
 *  tilt.x / tilt.y run -1..1 (right / toward you). They are relative to how the
 *  phone was first held and the baseline drifts back slowly, so a phone resting
 *  at 50 degrees reads as level, and the effect is about *changing* the angle.
 *  Screen rotation is accounted for. Smoothed, so a shaky hand is a calm one.
 *
 *  iOS only hands over orientation after a tap, so the first touch asks. On
 *  desktop, or if permission is refused, tilt.active stays false and each piece
 *  falls back to its own pointer or drift behaviour.
 *
 *  Pages import this by the same URL so there is exactly one instance.
 */
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

const tilt = { x: 0, y: 0, active: false, listeners: new Set() };
let base = null;
let rx = 0;
let ry = 0;
let started = false;
let lastT = 0;

function read(ev) {
    if (ev.beta == null || ev.gamma == null) return;
    const ang = (screen.orientation && screen.orientation.angle) || window.orientation || 0;
    const b = ev.beta;
    const g = ev.gamma;
    let x;
    let y;
    switch (((ang % 360) + 360) % 360) {
        case 90:  x = b;  y = -g; break;
        case 180: x = -g; y = -b; break;
        case 270: x = -b; y = g;  break;
        default:  x = g;  y = b;
    }
    const now = performance.now();
    const dt = lastT ? Math.min(0.2, (now - lastT) / 1000) : 0.016;
    lastT = now;
    if (!base) base = { x, y };
    // the baseline eases toward wherever the phone is now (about 12s to settle)
    const k = 1 - Math.exp(-dt / 12);
    base.x += (x - base.x) * k;
    base.y += (y - base.y) * k;
    rx = clamp((x - base.x) / 24, -1, 1);
    ry = clamp((y - base.y) / 24, -1, 1);
    // low-pass
    const s = 1 - Math.exp(-dt / 0.09);
    tilt.x += (rx - tilt.x) * s;
    tilt.y += (ry - tilt.y) * s;
    if (!tilt.active) {
        tilt.active = true;
        tilt.listeners.forEach((fn) => fn(tilt));
    }
}

function listen() {
    if (started) return;
    started = true;
    addEventListener('deviceorientation', read, { passive: true });
}

if (typeof DeviceOrientationEvent !== 'undefined') {
    // Listening costs nothing and works wherever no permission is needed
    // (Android, and Chrome which grants it quietly). iOS stays silent until the
    // user taps, so also ask on the first touch.
    listen();
    if (typeof DeviceOrientationEvent.requestPermission === 'function') {
        addEventListener('touchend', () => {
            DeviceOrientationEvent.requestPermission()
                .then((st) => { if (st === 'granted') listen(); })
                .catch(() => {});
        }, { once: true, passive: true });
    }
}

// Desktop browsers fire one null event; only a real sensor flips .active.
export default tilt;

/* jali-light: the figure is the room. Prefix .jl- */
[data-jali-light] {
    position: relative;
    display: block;
    margin: 0;
    width: 100%;
    height: 88svh;
    min-height: 460px;
    overflow: hidden;
    background: #14100d;
    touch-action: pan-y;
    cursor: ew-resize;
    -webkit-tap-highlight-color: transparent;
    outline: none;
}
[data-jali-light]:focus-visible { outline: 2px solid var(--accent, #c96f4a); outline-offset: -6px; }

/* without script: the screens in a row you can scroll along */
[data-jali-light]:not(.jl-on) { display: flex; gap: 4vw; overflow-x: auto; align-items: center; padding: 0 8vw; scroll-snap-type: x mandatory; }
[data-jali-light]:not(.jl-on) > img { flex: none; height: 70%; width: auto; scroll-snap-align: center; }
[data-jali-light].jl-on > img { display: none; }

.jl-room, .jl-air, .jl-dust { position: absolute; inset: 0; width: 100%; height: 100%; display: block; pointer-events: none; }

/* shafts of sun and dust add light to what is under them */
.jl-air, .jl-dust { mix-blend-mode: screen; }

/* the pinned walk: the page scroll is the way along the wall */
.jl-track.jl-pinned { height: calc(100svh + (var(--jl-n, 4) - 1) * 70svh); }
.jl-track.jl-pinned > [data-jali-light] { position: sticky; top: 0; height: 100svh; }

.jl-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---- orbs: glass hung in the room (orbs.js). --jl-sun / --jl-sky are "r,g,b" set from the hour ---- */
.jl-vr { position: absolute; inset: 0; perspective: 900px; pointer-events: none; overflow: hidden; }
.jl-obj, .jl-pool { position: absolute; left: 0; top: 0; width: 0; height: 0; }
.jl-par { transform: translate3d(calc(var(--jl-px, 0) * var(--par, 10px)), calc(var(--jl-py, 0) * var(--par, 10px) * .55), 0); }
.jl-bob { animation: jl-bob var(--jl-dur, 7s) ease-in-out var(--jl-delay, 0s) infinite alternate; }
