/* the shadow on the floor, with a small bright pool where the glass gathers the light */
.jl-pool { pointer-events: none; }
.jl-pool::before, .jl-pool::after { content: ""; position: absolute; border-radius: 50%; transform: translate(-50%, -50%); }
.jl-pool::before { width: calc(var(--d) * 2.1); height: calc(var(--d) * .62);
    background: radial-gradient(closest-side, rgba(2, 1, 0, .95), rgba(2, 1, 0, .62) 40%, rgba(2, 1, 0, .2) 74%, rgba(6, 4, 2, 0)); }
.jl-pool::after { width: calc(var(--d) * .72); height: calc(var(--d) * .15); mix-blend-mode: screen;
    background: radial-gradient(closest-side, rgba(var(--jl-sun, 255, 214, 150), calc(.18 + .5 * var(--jl-warm, 1))), rgba(var(--jl-sun, 255, 214, 150), 0)); }

.jl-orb {
    position: absolute; left: calc(var(--d) / -2); top: calc(var(--d) / -2);
    width: var(--d); height: var(--d); padding: 0; margin: 0; border: 0; border-radius: 50%;
    display: grid; place-items: center; overflow: hidden; cursor: pointer; pointer-events: auto;
    color: #fff4e2; -webkit-tap-highlight-color: transparent; touch-action: manipulation;
    background:
        radial-gradient(circle at 50% 50%, rgba(255, 246, 228, 0) 58%, rgba(255, 246, 228, .22) 82%, rgba(255, 246, 228, .62) 99%),
        radial-gradient(circle at 36% 28%, rgba(255, 250, 240, .5), rgba(255, 246, 230, .1) 24%, rgba(255, 244, 226, 0) 44%),
        radial-gradient(circle at 40% 32%, rgba(255, 246, 228, .1), rgba(40, 28, 18, .2) 62%, rgba(14, 9, 5, .55) 100%);
    -webkit-backdrop-filter: blur(5px) saturate(1.45) brightness(1.18); backdrop-filter: blur(5px) saturate(1.45) brightness(1.18);
    box-shadow:
        inset 0 0 0 1px rgba(255, 244, 224, .45),
        inset calc(var(--d) * -.06) calc(var(--d) * -.1) calc(var(--d) * .22) rgba(var(--jl-sun, 255, 214, 150), .5),
        inset calc(var(--d) * .05) calc(var(--d) * .07) calc(var(--d) * .14) rgba(255, 255, 255, .3),
        inset 0 calc(var(--d) * -.2) calc(var(--d) * .3) rgba(10, 6, 3, .35),
        0 calc(var(--d) * .1) calc(var(--d) * .22) rgba(0, 0, 0, .4),
        0 0 calc(var(--d) * .4) rgba(var(--jl-sun, 255, 214, 150), .16);
    transition: transform .45s cubic-bezier(.2, .8, .2, 1), box-shadow .45s ease;
    transform: rotateY(calc(var(--jl-px, 0) * 16deg)) rotateX(calc(var(--jl-py, 0) * -11deg));
}
.jl-lace { position: absolute; inset: 0; width: 100%; height: 100%; mix-blend-mode: screen; opacity: 1; pointer-events: none; }
.jl-glyph { position: relative; width: 36%; height: 36%; filter: drop-shadow(0 1px 6px rgba(0, 0, 0, .35)); }
.jl-gloss { position: absolute; inset: 0; border-radius: 50%; pointer-events: none;
    background:
        radial-gradient(34% 22% at 34% 15%, rgba(255, 255, 255, .55), rgba(255, 255, 255, 0)),
        radial-gradient(60% 20% at 60% 96%, rgba(var(--jl-sun, 255, 214, 150), .3), rgba(var(--jl-sun, 255, 214, 150), 0)); }
.jl-orb:hover, .jl-orb:focus-visible {
    transform: rotateY(calc(var(--jl-px, 0) * 16deg)) rotateX(calc(var(--jl-py, 0) * -11deg)) translateZ(46px) scale(1.1);
    box-shadow:
        inset 0 0 0 1.5px rgba(255, 246, 228, .75),
        inset 0 calc(var(--d) * -.12) calc(var(--d) * .3) rgba(var(--jl-sun, 255, 214, 150), .6),
        inset 0 calc(var(--d) * .08) calc(var(--d) * .2) rgba(255, 255, 255, .3),
        0 calc(var(--d) * .12) calc(var(--d) * .3) rgba(0, 0, 0, .3),
        0 0 calc(var(--d) * .8) rgba(var(--jl-sun, 255, 214, 150), .45);
}
.jl-orb:focus-visible { outline: 2px solid var(--accent, #c96f4a); outline-offset: 7px; }
.jl-tag { position: absolute; left: 50%; top: calc(var(--d) / 2 + 16px); transform: translate(-50%, -4px); white-space: nowrap; pointer-events: none;
    font: italic 500 21px/1 var(--serif, Georgia, serif); letter-spacing: .03em; color: #fff8ea; text-shadow: 0 1px 14px rgba(0, 0, 0, .85), 0 0 3px rgba(0, 0, 0, .7), 0 0 22px rgba(0, 0, 0, .55);
    opacity: 0; transition: opacity .35s ease, transform .35s ease; }
.jl-orb:hover + .jl-tag, .jl-orb:focus-visible + .jl-tag { opacity: 1; transform: translate(-50%, 0); }
.jl-vr.jl-away { opacity: .5; transition: opacity .4s ease; }

/* ---- the gaze reticle ---- */
.jl-gaze { cursor: none; }
.jl-gaze .jl-orb, .jl-gaze .jl-scrim, .jl-gaze .jl-scrim * { cursor: none; }
.jl-gaze .jl-scrim button, .jl-gaze .jl-scrim a { cursor: pointer; }
.jl-reticle { position: absolute; left: -30px; top: -30px; width: 60px; height: 60px; pointer-events: none; z-index: 5; opacity: 1; transition: opacity .25s ease; }
.jl-reticle svg { width: 100%; height: 100%; overflow: visible; transform: scale(.44); transition: transform .45s cubic-bezier(.2, .8, .2, 1); }
.jl-reticle circle { fill: none; stroke: rgba(255, 246, 228, .9); stroke-width: 2; vector-effect: non-scaling-stroke; filter: drop-shadow(0 0 3px rgba(0, 0, 0, .55)); }
.jl-reticle .jl-r-ring { stroke-width: 1.4; stroke-opacity: .85; }
.jl-reticle .jl-r-dot { fill: rgba(255, 246, 228, .95); stroke: none; }
.jl-reticle .jl-r-fill { stroke: rgb(var(--jl-sun, 255, 214, 150)); stroke-width: 2.4; stroke-linecap: round; stroke-dasharray: 100; stroke-dashoffset: 100; transform: rotate(-90deg); transform-origin: 30px 30px; transition: stroke-dashoffset .7s cubic-bezier(.3, .7, .2, 1); }
.jl-reticle.jl-lock svg { transform: scale(1); }
.jl-reticle.jl-lock .jl-r-fill { stroke-dashoffset: 0; }
