.jl-reticle.jl-lock.jl-press svg { transform: scale(.82); }
.jl-reticle.jl-hide { opacity: 0; }
.jl-reticle:not(.jl-tap):not(.jl-lock) { }
.jl-reticle.jl-tap svg { animation: jl-tap .7s ease-out both; }
@keyframes jl-tap { from { transform: scale(.4); opacity: 1; } to { transform: scale(1.1); opacity: 0; } }
[data-jali-light]:not(.jl-gaze) .jl-reticle:not(.jl-tap) { opacity: 0; }

/* ---- an orb opened: a floating glass window that unfolds out of it ---- */
.jl-scrim { position: absolute; inset: 0; z-index: 6; display: grid; place-items: center; padding: 14px; cursor: default; touch-action: pan-y;
    background: radial-gradient(closest-side at 50% 52%, rgba(10, 7, 4, .32), rgba(10, 7, 4, .6)); opacity: 0; transition: opacity .3s ease; perspective: 1100px; }
.jl-scrim.jl-in { opacity: 1; }
.jl-scrim.jl-out { opacity: 0; transition-duration: .22s; }
.jl-app-win {
    position: relative; width: min(440px, 100%); max-height: 100%; overflow: auto; overscroll-behavior: contain;
    color: #fbf1df; font-family: var(--text, Georgia, serif); font-size: 17px; line-height: 1.45;
    border-radius: 26px; padding: 26px 24px 22px;
    background: linear-gradient(160deg, rgba(255, 246, 230, .2), rgba(255, 246, 230, .07) 50%, rgba(255, 238, 212, .11));
    -webkit-backdrop-filter: blur(26px) saturate(1.35); backdrop-filter: blur(26px) saturate(1.35);
    box-shadow: inset 0 0 0 1px rgba(255, 244, 224, .34), inset 0 1px 0 rgba(255, 255, 255, .35), inset 0 -40px 80px rgba(var(--jl-sun, 255, 214, 150), .12), 0 30px 80px rgba(0, 0, 0, .55);
    transform-origin: var(--ox, 50%) var(--oy, 50%); transform: scale(.35) rotateX(-14deg); opacity: 0;
    transition: transform .55s cubic-bezier(.16, .9, .2, 1), opacity .3s ease;
}
.jl-in .jl-app-win { transform: none; opacity: 1; }
.jl-out .jl-app-win { transform: scale(.5) rotateX(-10deg); opacity: 0; transition-duration: .22s; }
.jl-app-win[data-app="code"] { width: min(560px, 100%); padding: 0; background: linear-gradient(160deg, rgba(34, 26, 18, .72), rgba(22, 16, 11, .82)); }
.jl-app-win[data-app="gallery"] { width: min(560px, 100%); padding: 14px; }
.jl-x { position: absolute; top: 12px; right: 12px; z-index: 2; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 50%; display: grid; place-items: center; cursor: pointer;
    color: #fbf1df; background: rgba(255, 244, 224, .14); box-shadow: inset 0 0 0 1px rgba(255, 244, 224, .3); transition: background .25s ease; touch-action: manipulation; }
.jl-x svg { width: 16px; height: 16px; }
.jl-x:hover { background: rgba(255, 244, 224, .26); }
.jl-app-win button:focus-visible, .jl-app-win a:focus-visible, .jl-src:focus-visible { outline: 2px solid #e3b66a; outline-offset: 3px; }
.jl-a h2 { margin: 0; font-family: var(--serif, Georgia, serif); font-weight: 400; }
