    background: radial-gradient(circle at 32% 26%, #e9c58f, #b9835a 55%, #7a4f39); box-shadow: inset 0 0 0 1.5px rgba(255, 244, 224, .55), 0 10px 26px rgba(0, 0, 0, .35); }
