.jl-go { width: 20px; height: 20px; flex: none; opacity: .8; }

/* code */
.jl-tabs { display: flex; gap: 2px; padding: 12px 56px 0 14px; border-bottom: 1px solid rgba(255, 244, 224, .14); }
.jl-tabs button { display: flex; align-items: center; gap: 8px; padding: 9px 14px 10px; border: 0; border-radius: 10px 10px 0 0; cursor: pointer; background: none; color: rgba(251, 241, 223, .55);
    font: 500 13.5px/1 ui-monospace, 'SF Mono', Menlo, Consolas, monospace; touch-action: manipulation; }
.jl-tabs button[aria-selected="true"] { color: #fbf1df; background: rgba(255, 244, 224, .1); box-shadow: inset 0 1px 0 #e3b66a; }
.jl-dot { width: 7px; height: 7px; border-radius: 50%; background: #e3b66a; }
.jl-dot-md { background: #9db08a; }
.jl-src { margin: 0; padding: 16px 18px 18px 6px; overflow: auto; max-height: min(52vh, 380px);
    font: 400 13.5px/1.75 ui-monospace, 'SF Mono', Menlo, Consolas, monospace; color: #efe2cc; tab-size: 2; white-space: pre; }
.jl-l { display: block; }
.jl-l u { display: inline-block; width: 3em; padding-right: 1.2em; text-align: right; text-decoration: none; color: rgba(251, 241, 223, .28); user-select: none; }
.jl-t-k { color: #e3b66a; } .jl-t-s { color: #d98a63; } .jl-t-c { color: #8f8a7f; font-style: italic; } .jl-t-n { color: #c3a7d9; }
.jl-t-f { color: #f1d9a4; } .jl-t-p { color: #efe2cc; } .jl-t-o { color: #b9ad9a; }
.jl-caret { display: inline-block; width: .55em; height: 1.15em; margin: 0 0 -.2em .15em; background: #e3b66a; animation: jl-blink 1.1s steps(2, start) infinite; }
@keyframes jl-blink { to { visibility: hidden; } }
.jl-status { display: flex; gap: 16px; padding: 9px 18px 11px; border-top: 1px solid rgba(255, 244, 224, .12); font: 500 11.5px/1 ui-monospace, 'SF Mono', Menlo, monospace; color: rgba(251, 241, 223, .5); }
.jl-status .jl-ln { margin-left: auto; }

/* social */
.jl-a-head { font-size: 30px; margin: 0 40px 14px 2px; }
.jl-feed { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
.jl-post { display: grid; grid-template-columns: 42px 1fr; gap: 12px; padding: 14px 4px; border-top: 1px solid rgba(255, 244, 224, .14); }
.jl-pa { width: 42px; height: 42px; border-radius: 50%; background: radial-gradient(circle at 32% 26%, color-mix(in srgb, var(--c) 55%, #fff), var(--c) 60%, color-mix(in srgb, var(--c) 60%, #000));
    box-shadow: inset 0 0 0 1px rgba(255, 244, 224, .4); }
.jl-pn { margin: 0; line-height: 1.2; } .jl-pn b { font-weight: 600; } .jl-pn i { font-style: normal; color: rgba(251, 241, 223, .55); font-size: 15px; margin-left: 4px; }
.jl-pt { margin: 3px 0 8px; text-wrap: pretty; }
.jl-like { display: inline-flex; align-items: center; gap: 7px; min-height: 36px; padding: 0 12px 0 8px; margin-left: -8px; border: 0; border-radius: 18px; cursor: pointer; background: none; color: rgba(251, 241, 223, .7);
    font: 500 15px/1 var(--text, Georgia, serif); transition: color .25s ease, background .25s ease; touch-action: manipulation; }
.jl-like svg { width: 20px; height: 20px; transition: transform .35s cubic-bezier(.3, 1.6, .4, 1); }
.jl-like:hover { background: rgba(255, 244, 224, .1); }
.jl-like[aria-pressed="true"] { color: #f0a483; }
.jl-like[aria-pressed="true"] svg { fill: #e58b68; stroke: #e58b68; transform: scale(1.12); }

/* gallery */
.jl-frame { position: relative; aspect-ratio: 4 / 3; border-radius: 16px; overflow: hidden; background: #14100d; box-shadow: inset 0 0 0 1px rgba(255, 244, 224, .2); }
.jl-frame > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; }
.jl-pv, .jl-nx { position: absolute; top: 50%; width: 42px; height: 42px; margin-top: -21px; padding: 0; border: 0; border-radius: 50%; display: grid; place-items: center; cursor: pointer;
    color: #fbf1df; background: rgba(20, 15, 10, .5); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); box-shadow: inset 0 0 0 1px rgba(255, 244, 224, .3); touch-action: manipulation; }
.jl-pv { left: 10px; } .jl-nx { right: 10px; }
.jl-pv svg, .jl-nx svg { width: 20px; height: 20px; }
.jl-thumbs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-top: 10px; }
.jl-thumbs button { padding: 0; aspect-ratio: 1.15; border: 0; border-radius: 10px; overflow: hidden; cursor: pointer; background: #14100d; opacity: .55; box-shadow: inset 0 0 0 1px rgba(255, 244, 224, .2); transition: opacity .25s ease, box-shadow .25s ease; }
.jl-thumbs button[aria-current="true"] { opacity: 1; box-shadow: 0 0 0 2px #e3b66a; }
.jl-thumbs img { width: 100%; height: 100%; object-fit: cover; display: block; }

@media (max-width: 639px) {
    .jl-app-win { padding: 22px 18px 18px; border-radius: 22px; }
    .jl-a-name { font-size: 34px; }
    .jl-tag { font-size: 19px; }
    .jl-src { font-size: 12.5px; }
}
@media (prefers-reduced-motion: reduce) {
    .jl-bob, .jl-caret, .jl-reticle.jl-tap svg { animation: none; }
    .jl-par { transform: none; }
    .jl-orb, .jl-orb:hover, .jl-orb:focus-visible { transition: none; transform: none; }
    .jl-orb:hover, .jl-orb:focus-visible { transform: scale(1.06); }
    .jl-app-win, .jl-scrim { transition: none; transform: none; }
    .jl-scrim { opacity: 1; }
    .jl-app-win { opacity: 1; }
}
